// Kanto dialogue: append-only remembered IDs.
static const u8 sPipAdventure_PEWTER_CITY_0[] = _("PIP: Even the museum has rocks.\nBROCK must feel very supported.$");
static const u8 sPipAdventure_PEWTER_CITY_1[] = _("PIP: That bench has survived more\ntrainers than I have.$");
static const u8 sPipAdventure_CERULEAN_CITY_0[] = _("PIP: Five battles on one bridge.\nA toll booth would be less\lpersonal.$");
static const u8 sPipAdventure_CERULEAN_CITY_1[] = _("PIP: A water GYM. My shoes did\nnot prepare for this.$");
static const u8 sPipAdventure_VERMILION_CITY_0[] = _("PIP: Everyone here knows a\nsailor. I know a knot. It is in\lmy shoe.$");
static const u8 sPipAdventure_VERMILION_CITY_1[] = _("PIP: I packed for a cruise. My\nbag contains one sandwich.$");
static const u8 sPipAdventure_LAVENDER_TOWN_0[] = _("PIP: We can sit for a minute.\nNobody needs us to be funny here.$");
static const u8 sPipAdventure_LAVENDER_TOWN_1[] = _("PIP: Someone still tends those\nflowers. I am glad they do.$");
static const u8 sPipAdventure_CELADON_CITY_0[] = _("PIP: My allowance has requested\nthat we avoid the department\lstore.$");
static const u8 sPipAdventure_CELADON_CITY_1[] = _("PIP: So many roofs. Somewhere a\nPIDGEY is charging rent.$");
static const u8 sPipAdventure_FUCHSIA_CITY_0[] = _("PIP: The SAFARI ZONE has a timer.\nFinally, a rule my lunch\lrespects.$");
static const u8 sPipAdventure_FUCHSIA_CITY_1[] = _("PIP: I waved at a rare POKéMON.\nIt has chosen to remain rare.$");
static const u8 sPipAdventure_SAFFRON_CITY_0[] = _("PIP: I took three turns and ended\nup behind myself. Excellent\lplanning.$");
static const u8 sPipAdventure_SAFFRON_CITY_1[] = _("PIP: SILPH makes useful\ninventions. I would like a bag\lwith cupholders.$");
static const u8 sPipAdventure_CINNABAR_ISLAND_0[] = _("PIP: An island, a lab, and a\nvolcano. Someone approved this\larrangement.$");
static const u8 sPipAdventure_CINNABAR_ISLAND_1[] = _("PIP: The sea breeze is nice. The\nvolcano breeze is less nice.$");
static const u8 sPipAdventure_INDIGO_PLATEAU_0[] = _("PIP: I had a speech ready. It has\nbecome mostly breathing.$");
static const u8 sPipAdventure_INDIGO_PLATEAU_1[] = _("PIP: Before we go in, eat\nsomething. Heroism is hungry\lwork.$");
static const u8 sPipAdventure_VIRIDIAN_FOREST_0[] = _("PIP: Every rustle sounds\nenormous. Then a tiny bug walks\lout, offended.$");
static const u8 sPipAdventure_VIRIDIAN_FOREST_1[] = _("PIP: The trees made a ceiling.\nVery thoughtful. Slightly damp.$");
static const u8 sPipAdventure_MT_MOON_0[] = _("PIP: A mountain named after the\nmoon. The moon has declined to\lcomment.$");
static const u8 sPipAdventure_MT_MOON_1[] = _("PIP: If a fossil bites us, I am\nrequesting a refund.$");
static const u8 sPipAdventure_ROCK_TUNNEL_0[] = _("PIP: A new shade of dark. It is\ncalled more dark.$");
static const u8 sPipAdventure_ROCK_TUNNEL_1[] = _("PIP: That rock looks familiar.\nPlease tell me it is its cousin.$");
static const u8 sPipAdventure_POKEMON_TOWER_0[] = _("PIP: I will keep my voice down.\nYou can take your time.$");
static const u8 sPipAdventure_POKEMON_TOWER_1[] = _("PIP: It is good that someone\nremembers them. Even when it is\lhard.$");
static const u8 sPipAdventure_ROCKET_HIDEOUT_0[] = _("PIP: They put arrows on the\nfloor. Crime has good signage.$");
static const u8 sPipAdventure_ROCKET_HIDEOUT_1[] = _("PIP: A base under a game corner.\nI assumed it was more game\lcorner.$");
static const u8 sPipAdventure_SILPH_CO_0[] = _("PIP: An office building in\ndanger, and the elevator still\lworks.$");
static const u8 sPipAdventure_SILPH_CO_1[] = _("PIP: That employee kept their\nlunch. A sensible priority.$");
static const u8 sPipAdventure_SAFARI_ZONE_0[] = _("PIP: The POKéMON have no\nschedule. We are the exhibit with\la timer.$");
static const u8 sPipAdventure_SAFARI_ZONE_1[] = _("PIP: The grass is moving. I am\ntrying to look approachable.$");
static const u8 sPipAdventure_POKEMON_MANSION_0[] = _("PIP: Dusty furniture. At last, my\nhousekeeping equals theirs.$");
static const u8 sPipAdventure_POKEMON_MANSION_1[] = _("PIP: A diary is lying open. I\nhope it is not about us.$");
static const u8 sPipAdventure_SEAFOAM_ISLANDS_0[] = _("PIP: Ice, water, and boulders. My\nleast convenient stairs.$");
static const u8 sPipAdventure_SEAFOAM_ISLANDS_1[] = _("PIP: If I slip, please call it a\ndramatic entrance.$");
static const u8 sPipAdventure_VICTORY_ROAD_0[] = _("PIP: The name sounds encouraging.\nThe boulders have other opinions.$");
static const u8 sPipAdventure_VICTORY_ROAD_1[] = _("PIP: I thought victory came with\na road. We supply the road.$");
static const u8 sPipAdventure_POWER_PLANT_0[] = _("PIP: The lights are off. The\nresidents are extremely on.$");
static const u8 sPipAdventure_POWER_PLANT_1[] = _("PIP: Do not unplug anything. It\nmight be somebody.$");
static const u8 sPipAdventure_ONE_ISLAND_0[] = _("PIP: A warm breeze and a quiet\nharbor. I could get used to this\lbench.$");
static const u8 sPipAdventure_ONE_ISLAND_1[] = _("PIP: Another island. Another\nchance to forget where I put my\lhat.$");
static const u8 sPipAdventure_TWO_ISLAND_0[] = _("PIP: That shop sells everything.\nI am looking for a second pocket.$");
static const u8 sPipAdventure_TWO_ISLAND_1[] = _("PIP: Small towns make excellent\ngossip. Little delivery distance.$");
static const u8 sPipAdventure_THREE_ISLAND_0[] = _("PIP: A forest at the edge of\ntown. The trees have excellent\ltiming.$");
static const u8 sPipAdventure_THREE_ISLAND_1[] = _("PIP: We should help before we\nlecture. I can lecture while\lwalking.$");
static const u8 sPipAdventure_FOUR_ISLAND_0[] = _("PIP: Daycare has the right idea.\nSomeone else handles the\lexercise.$");
static const u8 sPipAdventure_FOUR_ISLAND_1[] = _("PIP: Ice in a tropical cave. The\nweather has lost its notes.$");
static const u8 sPipAdventure_FIVE_ISLAND_0[] = _("PIP: Please let this be a\nrelaxing walk. I scheduled the\lrelaxing.$");
static const u8 sPipAdventure_FIVE_ISLAND_1[] = _("PIP: Someone planted flowers\nhere. A good use of a day.$");
static const u8 sPipAdventure_SIX_ISLAND_0[] = _("PIP: These ruins lasted ages. My\nshoes are entering retirement.$");
static const u8 sPipAdventure_SIX_ISLAND_1[] = _("PIP: If the inscription says\npush, I would appreciate a\lpicture.$");
static const u8 sPipAdventure_SEVEN_ISLAND_0[] = _("PIP: Seven islands. Still one\npair of socks that I actually\llike.$");
static const u8 sPipAdventure_SEVEN_ISLAND_1[] = _("PIP: Ruins are history with fresh\nair. I like this museum policy.$");
static const u8 sPipAdventure_BROCK[] = _("PIP: He stays calm when rocks\nfly. I flinch when somebody drops\la spoon.$");
static const u8 sPipAdventure_MISTY[] = _("PIP: A pool inside a GYM. I\nshould have brought other shoes.$");
static const u8 sPipAdventure_LT_SURGE[] = _("PIP: He calls it a shock. I\nprefer warnings with\lmeasurements.$");
static const u8 sPipAdventure_ERIKA[] = _("PIP: She made training look\nrestful. I have been practicing\lthat part.$");
static const u8 sPipAdventure_KOGA[] = _("PIP: A ninja who announces his\nname. Very considerate for a\lninja.$");
static const u8 sPipAdventure_SABRINA[] = _("PIP: I was going to make a joke.\nShe probably heard the first\ldraft.$");
static const u8 sPipAdventure_BLAINE[] = _("PIP: A quiz before a battle. He\ncombined my two anxieties.$");
static const u8 sPipAdventure_GIOVANNI[] = _("PIP: A GYM and a criminal empire.\nI cannot manage two errands.$");
static const u8 sPipAdventure_PROF_OAK[] = _("PIP: He really loves his\nresearch. I hope someone reminds\lhim to eat.$");
static const u8 sPipAdventure_BLUE[] = _("PIP: He practices being ahead of\nus. Exhausting to stand there.$");
